  1→//! Configuration loading, parsing, and validation for Bivvy.
  2→//!
  3→//! This module handles all aspects of configuration:
  4→//! - Schema definitions in [`schema`]
  5→//! - File discovery and loading in [`loader`]
  6→//! - Deep merging in [`merger`]
  7→//! - Validation in [`validator`]
  8→//! - Variable interpolation in [`interpolation`]
  9→//! - Environment variable handling in [`environment`]
 10→//!
 11→//! # Example
 12→//!
 13→//! ```
 14→//! use bivvy::config::{load_merged_config, validate};
 15→//! use tempfile::TempDir;
 16→//! use std::fs;
 17→//!
 18→//! let temp = TempDir::new().unwrap();
 19→//! let bivvy_dir = temp.path().join(".bivvy");
 20→//! fs::create_dir_all(&bivvy_dir).unwrap();
 21→//! fs::write(bivvy_dir.join("config.yml"), "app_name: test").unwrap();
 22→//!
 23→//! let config = load_merged_config(temp.path()).unwrap();
 24→//! validate(&config).unwrap();
 25→//! assert_eq!(config.app_name, Some("test".to_string()));
 26→//! ```
 27→//!
 28→//! # Configuration File Locations
 29→//!
 30→//! Bivvy discovers and merges configuration in this order:
 31→//! 1. Remote base configs (from `extends:`)
 32→//! 2. User global config (`~/.bivvy/config.yml`)
 33→//! 3. Project config (`.bivvy/config.yml`)
 34→//! 4. Local overrides (`.bivvy/config.local.yml`)
