  1→//! Configuration file discovery and loading.
  2→//!
  3→//! This module handles finding and loading configuration files from
  4→//! various locations in the correct priority order.
  5→
  6→use crate::config::extends::ExtendsResolver;
  7→use crate::config::merger::merge_configs;
  8→use crate::config::schema::BivvyConfig;
  9→use crate::error::{BivvyError, Result};
 10→use std::fs;
 11→use std::path::{Path, PathBuf};
 12→
 13→/// Paths to configuration files in priority order (later overrides earlier).
 14→///
 15→/// Merge order:
 16→/// 1. Remote base configs (from `extends:`)
 17→/// 2. User global config (`~/.bivvy/config.yml`)
 18→/// 3. Project config (`.bivvy/config.yml`)
 19→/// 4. Local overrides (`.bivvy/config.local.yml`)
 20→#[derive(Debug, Clone)]
 21→pub struct ConfigPaths {
 22→    /// Remote base config (if extends: is used)
 23→    pub extends: Vec<PathBuf>,
 24→
 25→    /// User's global config: ~/.bivvy/config.yml
 26→    pub user_global: Option<PathBuf>,
 27→
 28→    /// Project config: .bivvy/config.yml
 29→    pub project: Option<PathBuf>,
 30→
 31→    /// Local overrides: .bivvy/config.local.yml
 32→    pub project_local: Option<PathBuf>,
 33→}
 34→
 35→impl ConfigPaths {
 36→    /// Discover config files for the given project root.
 37→    pub fn discover(project_root: &Path) -> Self {
 38→        Self {
 39→            extends: Vec::new(), // Populated later after parsing project config
 40→            user_global: Self::find_user_global(),
 41→            project: Self::find_project_config(project_root),
 42→            project_local: Self::find_project_local(project_root),
 43→        }
 44→    }
 45→
 46→    /// Find user's global config at ~/.bivvy/config.yml
 47→    fn find_user_global() -> Option<PathBuf> {
 48→        let path = dirs::home_dir()?.join(".bivvy").join("config.yml");
 49→        if path.exists() {
 50→            Some(path)
 51→        } else {
 52→            None
 53→        }
 54→    }
 55→
 56→    /// Find project config at .bivvy/config.yml
 57→    fn find_project_config(project_root: &Path) -> Option<PathBuf> {
 58→        let path = project_root.join(".bivvy").join("config.yml");
 59→        if path.exists() {
 60→            Some(path)
 61→        } else {
 62→            None
 63→        }
 64→    }
 65→
 66→    /// Find local overrides at .bivvy/config.local.yml
 67→    fn find_project_local(project_root: &Path) -> Option<PathBuf> {
 68→        let path = project_root.join(".bivvy").join("config.local.yml");
 69→        if path.exists() {
 70→            Some(path)
 71→        } else {
 72→            None
 73→        }
 74→    }
 75→
 76→    /// Returns all existing config paths in merge order.
 77→    pub fn all_existing(&self) -> Vec<&PathBuf> {
 78→        let mut paths = Vec::new();
 79→
 80→        for p in &self.extends {
 81→            paths.push(p);
 82→        }
 83→
 84→        if let Some(p) = &self.user_global {
 85→            paths.push(p);
 86→        }
 87→
 88→        if let Some(p) = &self.project {
 89→            paths.push(p);
 90→        }
 91→
 92→        if let Some(p) = &self.project_local {
 93→            paths.push(p);
 94→        }
 95→
 96→        paths
 97→    }
 98→
 99→    /// Check if any project config exists.
100→    pub fn has_project_config(&self) -> bool {

  1→//! Command dispatching.
  2→//!
  3→//! This module provides the core command infrastructure:
  4→//! - [`Command`] trait for implementing commands
  5→//! - [`CommandResult`] for uniform result reporting
  6→//! - [`CommandDispatcher`] for routing CLI subcommands
  7→
  8→use std::path::{Path, PathBuf};
  9→
 10→use crate::cli::args::{Cli, Commands};
 11→use crate::error::Result;
 12→use crate::ui::UserInterface;
 13→
 14→/// Trait for command implementations.
 15→///
 16→/// Each CLI subcommand implements this trait to provide its execution logic.
 17→pub trait Command {
 18→    /// Execute the command.
 19→    ///
 20→    /// # Arguments
 21→    ///
 22→    /// * `ui` - User interface for displaying output and prompts
 23→    ///
 24→    /// # Returns
 25→    ///
 26→    /// A [`CommandResult`] indicating success/failure and exit code.
 27→    fn execute(&self, ui: &mut dyn UserInterface) -> Result<CommandResult>;
 28→}
 29→
 30→/// Result of command execution.
 31→#[derive(Debug)]
 32→pub struct CommandResult {
 33→    /// Whether the command succeeded.
 34→    pub success: bool,
 35→
 36→    /// Exit code to use (0 for success, non-zero for failure).
 37→    pub exit_code: i32,
 38→}
 39→
 40→impl CommandResult {
 41→    /// Create a successful result.
 42→    pub fn success() -> Self {
 43→        Self {
 44→            success: true,
 45→            exit_code: 0,
 46→        }
 47→    }
 48→
 49→    /// Create a failure result.
 50→    pub fn failure(exit_code: i32) -> Self {
 51→        Self {
 52→            success: false,
 53→            exit_code,
 54→        }
 55→    }
 56→}
 57→
 58→/// Dispatches CLI commands to their implementations.
 59→pub struct CommandDispatcher {
 60→    project_root: PathBuf,
 61→}
 62→
 63→impl CommandDispatcher {
 64→    /// Create a new dispatcher for the given project root.
 65→    pub fn new(project_root: PathBuf) -> Self {
 66→        Self { project_root }
 67→    }
 68→
 69→    /// Get the project root path.
 70→    pub fn project_root(&self) -> &Path {
 71→        &self.project_root
 72→    }
 73→
 74→    /// Dispatch and execute a command.
 75→    ///
 76→    /// Routes the CLI subcommand to the appropriate command implementation
 77→    /// and executes it.
 78→    pub fn dispatch(&self, cli: &Cli, ui: &mut dyn UserInterface) -> Result<CommandResult> {
 79→        match &cli.command {
 80→            Some(Commands::Run(args)) => {
 81→                let cmd = super::run::RunCommand::new(&self.project_root, args.clone());
 82→                cmd.execute(ui)
