  1→//! Shell command execution.
  2→
  3→use crate::error::{BivvyError, Result};
  4→use std::collections::HashMap;
  5→use std::io::{BufRead, BufReader};
  6→use std::path::Path;
  7→use std::process::{Command, Stdio};
  8→use std::sync::mpsc;
  9→use std::thread;
 10→use std::time::{Duration, Instant};
 11→
 12→/// Result of executing a shell command.
 13→#[derive(Debug, Clone)]
 14→pub struct CommandResult {
 15→    /// Exit code (None if killed by signal).
 16→    pub exit_code: Option<i32>,
 17→
 18→    /// Standard output.
 19→    pub stdout: String,
 20→
 21→    /// Standard error.
 22→    pub stderr: String,
 23→
 24→    /// Execution duration.
 25→    pub duration: Duration,
 26→
 27→    /// Whether command succeeded (exit code 0).
 28→    pub success: bool,
 29→}
 30→
 31→impl CommandResult {
 32→    /// Create a success result.
 33→    pub fn success(stdout: String, stderr: String, duration: Duration) -> Self {
 34→        Self {
 35→            exit_code: Some(0),
 36→            stdout,
 37→            stderr,
 38→            duration,
 39→            success: true,
 40→        }
 41→    }
 42→
 43→    /// Create a failure result.
 44→    pub fn failure(
 45→        exit_code: Option<i32>,
 46→        stdout: String,
 47→        stderr: String,
 48→        duration: Duration,
 49→    ) -> Self {
 50→        Self {
 51→            exit_code,
 52→            stdout,
 53→            stderr,
 54→            duration,
 55→            success: false,
 56→        }
 57→    }
 58→}
